def select_next_node(graph, unvisited_nodes):
    # Extract node attributes into lists for lex ordering
    clustering = [(graph.nodes[n]['clustering'], n) for n in unvisited_nodes]
    core = [(graph.nodes[n]['core_number'], n) for n in unvisited_nodes]
    betweenness = [(graph.nodes[n]['betweenness'], n) for n in unvisited_nodes]
    eigenvector = [(graph.nodes[n]['eigenvector'], n) for n in unvisited_nodes]
    degree = [(graph.nodes[n]['degree'], n) for n in unvisited_nodes]

    # Create mapping for quick access
    cluster_map = {n: c for c, n in clustering}
    core_map = {n: c for c, n in core}
    bet_map = {n: b for b, n in betweenness}
    eig_map = {n: e for e, n in eigenvector}
    deg_map = {n: d for d, n in degree}

    # Lexicographic ordering key function:
    # 1) clustering ascending (lower is better)
    # 2) core ascending (lower is better)
    # 3) betweenness descending (higher is better)
    # 4) eigenvector descending (higher is better)
    # 5) degree descending (higher is better)
    def lex_key(n):
        return (
            cluster_map[n],                      # low clustering first
            core_map[n],                         # low core number next
            -bet_map[n],                        # high betweenness next
            -eig_map[n],                        # high eigenvector next
            -deg_map[n]                        # high degree last
        )

    next_node = min(unvisited_nodes, key=lex_key)
    return next_node

import networkx as nx
import numpy as np

def select_next_node(graph, unvisited_nodes):
    def sigmoid(x):
        return 1 / (1 + np.exp(-x))

    avg_eigenvector_neigh = {}
    for node in unvisited_nodes:
        neighbors = list(graph.neighbors(node))
        if not neighbors:
            avg_eigenvector_neigh[node] = 0
        else:
            avg_eigenvector_neigh[node] = np.mean([graph.nodes[n]['eigenvector'] for n in neighbors])

    # Extract betweenness and core_number for all nodes once
    betweenness = {node: graph.nodes[node]['betweenness'] for node in unvisited_nodes}
    core_numbers = {node: graph.nodes[node]['core_number'] for node in unvisited_nodes}

    # Normalize betweenness centrality
    b_values = np.array(list(betweenness.values()))
    if b_values.max() == b_values.min():
        b_norm = {node: 0.5 for node in betweenness}
    else:
        b_norm = {node: (betweenness[node] - b_values.min())/(b_values.max() - b_values.min()) for node in betweenness}

    max_core = graph.graph['precomputed'].get('max_core_k', 1)

    scores = {}
    for node in unvisited_nodes:
        inv_core_factor = 1 - (core_numbers[node]/max_core)  # scaled inverse core number
        eig_diff = abs(graph.nodes[node]['eigenvector'] - avg_eigenvector_neigh[node])
        raw_score = b_norm[node] * inv_core_factor * eig_diff
        scores[node] = sigmoid(raw_score)

    next_node = max(scores, key=scores.get)
    return next_node

import numpy as np
import networkx as nx

def select_next_node(graph: nx.Graph, unvisited_nodes: list):
    # Extract precomputed graph features
    avg_degree = graph.graph['precomputed'].get('avg_degree', 1)

    # Gather features for unvisited nodes
    closeness = nx.closeness_centrality(graph)  # closeness not precomputed; compute once outside ideally
    degree = {node: graph.nodes[node]['degree'] for node in unvisited_nodes}
    clustering = {node: graph.nodes[node]['clustering'] for node in unvisited_nodes}
    core_num = {node: graph.nodes[node]['core_number'] for node in unvisited_nodes}
    betweenness = {node: graph.nodes[node]['betweenness'] for node in unvisited_nodes}
    eigenvector = {node: graph.nodes[node]['eigenvector'] for node in unvisited_nodes}

    # Normalize helper
    def normalize_dict(d):
        values = np.array(list(d.values()))
        min_v, max_v = values.min(), values.max()
        if max_v - min_v == 0:
            return {k: 0.0 for k in d}
        return {k: (v - min_v) / (max_v - min_v) for k, v in d.items()}

    norm_closeness = normalize_dict({n: closeness[n] for n in unvisited_nodes})
    norm_clustering = normalize_dict(clustering)
    norm_core = normalize_dict(core_num)
    norm_degree = normalize_dict(degree)
    norm_eigenvector = normalize_dict(eigenvector)

    scores = {}
    for node in unvisited_nodes:
        c1 = norm_closeness[node] ** 1.1
        c2 = (1 - norm_clustering[node]) ** 1.5
        c3 = norm_core[node] * np.log(np.e + norm_degree[node])  # log base e, shift by e to keep >0
        c4 = norm_eigenvector[node] ** 0.8
        score = 0.4 * c1 + 0.3 * c2 + 0.2 * c3 + 0.1 * c4
        scores[node] = score

    # Select node with max score
    next_node = max(scores, key=scores.get)
    return next_node
